#include <spacerad/OrbitEnvironment.h>
#include <spacerad/ImportanceConfig.h>
#include <QCoreApplication>
#include <QDir>
#include <QFile>
#include <QFileInfo>
#include <QEventLoop>
#include <QPointer>
#include <QTimer>
#include <functional>
#include <iostream>
using namespace spacerad;
namespace {
Json checks=Json::array();void check(bool ok,const char* name){checks.push_back({{"name",name},{"passed",ok}});if(!ok)throw std::runtime_error(name);std::cout<<"PASS "<<name<<std::endl;}
bool rejects(std::function<void()> f){try{f();return false;}catch(...){return true;}}
QByteArray read(const QString& p){QFile f(p);if(!f.open(QIODevice::ReadOnly))throw std::runtime_error("Cannot read evidence");return f.readAll();}void write(const QString& p,const QByteArray& b){QFile f(p);if(!f.open(QIODevice::WriteOnly|QIODevice::Truncate)||f.write(b)!=b.size())throw std::runtime_error("Cannot save evidence");}
void wait(OrbitEnvironmentService& s){QEventLoop loop;QTimer timer;timer.setSingleShot(true);QObject::connect(&s,&OrbitEnvironmentService::stateChanged,&loop,[&](const QString& state){if(state=="completed"||state=="failed"||state=="cancelled")loop.quit();});QObject::connect(&timer,&QTimer::timeout,&loop,[&]{s.cancel();loop.quit();});timer.start(60000);if(s.running())loop.exec();}
}
int main(int argc,char** argv){QCoreApplication app(argc,argv);if(argc!=6)return 2;auto python=QFileInfo(QString::fromLocal8Bit(argv[1])).absoluteFilePath(),tools=QFileInfo(QString::fromLocal8Bit(argv[2])).absoluteFilePath(),ephem=QFileInfo(QString::fromLocal8Bit(argv[3])).absoluteFilePath(),runtimeFile=QString::fromLocal8Bit(argv[4]),out=QFileInfo(QString::fromLocal8Bit(argv[5])).absoluteFilePath();if(QFileInfo::exists(out)||!QDir().mkpath(out))return 2;bool passed=false;
try{auto p=configureImportanceSampling(Project::assemblyDemo(),.9,.05);auto before=p.toJson();OrbitModelRuntime runtime{python,tools,60};OrbitEnvironmentSettings settings;settings.ephemeris=ephem;OrbitEnvironmentService service;service.configure(runtime);int done=0,progress=0;QObject::connect(&service,&OrbitEnvironmentService::completed,&service,[&](const QByteArray&){++done;});QObject::connect(&service,&OrbitEnvironmentService::progress,&service,[&](int n,int total){if(n>=0&&n<=total)++progress;});service.start(p,settings,out+"/model");check(service.running(),"Real SpacePy model starts outside host process");check(rejects([&]{service.start(p,settings,out+"/busy");})&&!QFileInfo::exists(out+"/busy"),"Busy start rejected without output");check(rejects([&]{service.configure(runtime);}),"Running model runtime cannot be reconfigured");wait(service);if(service.state()!= "completed")throw std::runtime_error(read(out+"/model/model-job.json").toStdString());auto review=Json::parse(service.result().toStdString());check(done==1&&!service.result().isEmpty()&&progress>0,"Real model completes with progress and one accepted result");check(loadOrbitModelJob(out+"/model")==review,"Offline model job reconstructs accepted spectra without Python");auto generated=Project::fromJson(review.at("project"));check(generated.sourceSampling==p.sourceSampling&&p.toJson()==before,"Schema v8 sampling preserved and input project unchanged");check(generated.duration==680.896&&generated.spectra.size()==2,"External fractional ephemeris defines exact exposure and two modeled species");
    for(const char* file:{"input-ephemeris.csv","settings.json","model-tools/generate_ae8ap8_example.py","environment/project.json","environment/ae8min-integral-flux.csv","environment-review.json"}){auto path=out+"/model/"+file;auto saved=read(path);write(path,saved+" ");bool refused=rejects([&]{loadOrbitModelJob(out+"/model");});write(path,saved);check(refused,"Model job rejects changed input/script/raw/result artifact");}check(loadOrbitModelJob(out+"/model")==review,"Restored model archive validates");
    AnalysisService transport;transport.configure(loadRuntimeFile(runtimeFile));generated.events=3000;QEventLoop loop;QString error;QObject::connect(&transport,&AnalysisService::completed,&loop,&QEventLoop::quit);QObject::connect(&transport,&AnalysisService::failed,&loop,[&](const QString& e){error=e;loop.quit();});QTimer timer;timer.setSingleShot(true);QObject::connect(&timer,&QTimer::timeout,&loop,[&]{error="Transport timed out";transport.cancel();loop.quit();});timer.start(60000);transport.start(generated,out+"/transport");loop.exec();check(error.isEmpty()&&transport.state()=="completed"&&!transport.result().isEmpty(),"Generated environment completes actual Geant4 weighted transport");
    service.start(p,settings,out+"/cancel");service.cancel();wait(service);check(service.state()=="cancelled"&&service.result().isEmpty()&&done==1,"Model cancellation never accepts a spectrum");auto* dead=new OrbitEnvironmentService;dead->configure(runtime);dead->start(p,settings,out+"/destroy");delete dead;check(Json::parse(read(out+"/destroy/model-job.json").toStdString()).at("status")=="cancelled","Destroy active model terminates process and saves cancellation");
    auto* reentrant=new OrbitEnvironmentService;reentrant->configure(runtime);QPointer<OrbitEnvironmentService> alive=reentrant;QObject::connect(reentrant,&OrbitEnvironmentService::stateChanged,&app,[&](const QString& state){if(state=="running"&&alive)delete alive.data();});reentrant->start(p,settings,out+"/reentrant");check(alive.isNull(),"Host can destroy service directly from running signal");
    QDir().mkpath(out+"/fake-tools");write(out+"/fake-tools/generate_ae8ap8_example.py","import time\ntime.sleep(30)\n");write(out+"/fake-tools/ae8ap8_ephemeris.py","# timeout fixture\n");service.configure({python,out+"/fake-tools",1});service.start(p,settings,out+"/timeout");wait(service);check(service.state()=="failed"&&service.result().isEmpty(),"Model timeout stops process and publishes no result");write(out+"/fake-tools/generate_ae8ap8_example.py","import sys\nprint('invalid model values', file=sys.stderr)\nsys.exit(3)\n");service.start(p,settings,out+"/failure");wait(service);check(service.state()=="failed"&&Json::parse(read(out+"/failure/model-job.json").toStdString()).at("error").get<std::string>().find("invalid model values")!=std::string::npos,"Model stderr failure is actionable and does not fill missing values");passed=true;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';}write(out+"/summary.json",QByteArray::fromStdString(Json{{"passed",passed},{"checks",checks}}.dump(2)));std::cout<<checks.size()<<" real orbit model checks; passed="<<passed<<'\n';return passed?0:1;}
